<template><div class="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4" @click.self="$emit('close')"><form class="w-full max-w-lg space-y-5 rounded-xl border border-gray-700 bg-gray-800 p-6 shadow-2xl" @submit.prevent="save"><div><h2 class="text-xl font-semibold text-white">Edit item</h2><p class="mt-1 font-mono text-sm text-gray-400">{{item.barcode}}</p></div><div><label class="label">Name</label><input v-model="name" autofocus required class="field"></div><div><label class="label">Description</label><textarea v-model="description" rows="3" maxlength="2000" class="field" placeholder="Size, condition, what it's for…"></textarea></div><div><label class="label">Bin / location</label><select v-model="binId" class="field"><option value="">Unassigned</option><option v-for="bin in bins" :key="bin.id" :value="bin.id">{{binLabel(bin)}}</option></select><p v-if="item.checkedOutToId" class="mt-2 text-sm text-amber-300">This item is checked out. Its return location will apply after it is checked in.</p></div><div><label class="label">Category</label><select v-model="categoryId" class="field"><option value="">Uncategorized</option><option v-for="category in categories" :key="category.id" :value="category.id">{{category.name}}</option></select></div><div v-if="error" class="rounded-lg bg-red-900/50 p-3 text-sm text-red-200">{{error}}</div><div class="flex justify-end gap-2"><button type="button" class="rounded-lg bg-gray-700 px-4 py-2 text-white hover:bg-gray-600" @click="$emit('close')">Cancel</button><button :disabled="saving" class="rounded-lg bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-500 disabled:opacity-50">{{saving?'Saving…':'Save changes'}}</button></div></form></div></template>
<script setup lang="ts">import{ref}from'vue';import apiService from'@/services/api';import type{InventoryBin,InventoryCategory,InventoryItem}from'@/types/api';const props=withDefaults(defineProps<{item:InventoryItem;bins:InventoryBin[];categories?:InventoryCategory[]}>(),{categories:()=>[]}),emit=defineEmits<{close:[];saved:[item:InventoryItem]}>();const name=ref(props.item.name),description=ref(props.item.description||''),binId=ref(props.item.binId||''),categoryId=ref(props.item.categoryId||''),saving=ref(false),error=ref('');function binLabel(bin:InventoryBin){const parts=[bin.room,bin.shelf?`Shelf ${bin.shelf}`:''].filter(Boolean);return parts.length?`${parts.join(' · ')} · ${bin.name}`:bin.name}async function save(){saving.value=true;error.value='';try{emit('saved',await apiService.updateInventoryItem(props.item.id,{name:name.value,description:description.value.trim()||null,binId:binId.value||null,categoryId:categoryId.value||null}))}catch(e:any){error.value=e.response?.data?.error||'Could not update item'}finally{saving.value=false}}</script>
<style scoped>.label{@apply mb-2 block text-sm font-medium text-gray-300}.field{@apply w-full rounded-lg border border-gray-600 bg-gray-900 px-4 py-3 text-white focus:border-blue-500 focus:ring-2 focus:ring-blue-500/50}</style>
